function openExternalURL(url: string): void {
  try {
    const parsed = new URL(url)
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      shell.openExternal(parsed.toString())
    }
  } catch {
    // Ignore malformed renderer input.
  }
}

function previewURLTarget(contents: WebContents): WebContents {
  return contents.hostWebContents ?? contents
}

function canOpenPreviewURL(contents: WebContents): boolean {
  const target = previewURLTarget(contents)
  return !target.isDestroyed() && previewURLTargets.has(target.id)
}

function openPreviewURL(url: string, contents: WebContents): boolean {
  if (!canOpenPreviewURL(contents)) return false
  const target = previewURLTarget(contents)
  const win = BrowserWindow.fromWebContents(target)
  if (!win || win.isDestroyed()) return false
  win.show()
  win.focus()
  target.send('jaz:open-preview-url', url)
  return true
}

// Covers every window — main, preview webviews, and per-board windows.
app.on('web-contents-created', (_event, contents) => {
  contents.once('destroyed', () => previewURLTargets.delete(contents.id))
  attachBrowserNavigationShortcuts(contents)
  attachBrowserCloseShortcut(contents)
  attachPreviewFindShortcuts(contents)
  attachContextMenu(contents, { canOpenPreviewURL, openPreviewURL, backendOrigin: () => connectionSession.current().url })
  attachWindowOpenHandler(contents, shell.openExternal, (url) => openPreviewURL(url, contents))
})

function createWindow(): void {
  const mac = process.platform === 'darwin'
  // Opens filling the screen the pointer is on, under the boot splash.
  const { x, y, width, height } = screen.getDisplayNearestPoint(screen.getCursorScreenPoint()).workArea
  const win = new BrowserWindow({
    title: APP_NAME,
    x,
    y,
    width,
    height,
    minWidth: 940,
    minHeight: 600,
    show: false,
    icon: appIcon,
    // On macOS the window paints the native sidebar material; the renderer
    // keeps the content column opaque and lets the sidebar show through.
    backgroundColor: mac ? '#00000000' : nativeTheme.shouldUseDarkColors ? DARK_BG : '#ffffff',
    ...(mac ? { vibrancy: 'sidebar' as const, visualEffectState: 'followWindow' as const } : {}),
    titleBarStyle: mac ? 'hiddenInset' : 'default',
    trafficLightPosition: { x: 16, y: 13 },
    webPreferences: previewHostPreferences(join(__dirname, '../preload/index.js')),
  })

  mainWindow = win
  connectionSession.attach(win, true)
  attachVoiceOverlay(win)
  attachWindowLifecycle(win, { label: 'main', onDidFinishLoad: () => updates.sendStatusTo(win) })
  attachBrowserNavigationCommands(win)
  win.on('closed', () => {
    if (mainWindow === win) mainWindow = null
  })

  attachPreviewWebviews(win.webContents, join(__dirname, '../preload/index.js'))

  if (process.env['ELECTRON_RENDERER_URL']) {
    win.loadURL(process.env['ELECTRON_RENDERER_URL'])
  } else {
    win.loadFile(join(__dirname, '../renderer/index.html'))
  }
}

// Deep link from a board window into the main app (e.g. "Open loop").
function openInMain(path: string): void {
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.show()
    mainWindow.focus()
    mainWindow.webContents.send('jaz:open-route', path)
    return
  }
  createWindow()
  mainWindow?.webContents.once('did-finish-load', () => {
    mainWindow?.webContents.send('jaz:open-route', path)
  })
}

// Board windows: one OS window per board, bounds remembered locally (they are
// device-specific, unlike the board's tile layout which lives in the backend).
const boardWindows = new Map<string, BrowserWindow>()
const boardBoundsFile = (): string => join(app.getPath('userData'), 'board-windows.json')

function loadBoardBounds(): Record<string, Rectangle> {
  try {
    return JSON.parse(readFileSync(boardBoundsFile(), 'utf8')) as Record<string, Rectangle>
  } catch {
    return {}
  }
}

function saveBoardBounds(boardId: string, bounds: Rectangle): void {
  try {
    writeFileSync(boardBoundsFile(), JSON.stringify({ ...loadBoardBounds(), [boardId]: bounds }))
  } catch {
    // bounds are a convenience; never fail the close over them
  }
}

function openBoardWindow(boardId: string): void {
  const existing = boardWindows.get(boardId)
  if (existing && !existing.isDestroyed()) {
    existing.show()
    existing.focus()
    return
  }
  const saved = loadBoardBounds()[boardId]
  const win = new BrowserWindow({
    title: 'Board — Jaz',
    width: saved?.width ?? 960,
    height: saved?.height ?? 640,
    ...(saved ? { x: saved.x, y: saved.y } : {}),
    minWidth: 420,
    minHeight: 320,
    show: false,
    icon: appIcon,
    backgroundColor: nativeTheme.shouldUseDarkColors ? DARK_BG : '#ffffff',
    webPreferences: {
      preload: join(__dirname, '../preload/index.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
      additionalArguments: ['--jaz-board-window'],
    },
  })
  boardWindows.set(boardId, win)
  connectionSession.attach(win)
  attachWindowLifecycle(win, { label: `board ${boardId}` })
  attachBrowserNavigationCommands(win)
  win.on('close', () => saveBoardBounds(boardId, win.getBounds()))
  win.on('closed', () => boardWindows.delete(boardId))
  if (process.env['ELECTRON_RENDERER_URL']) {
    win.loadURL(`${process.env['ELECTRON_RENDERER_URL']}/boards/${boardId}`)
  } else {
    win.loadFile(join(__dirname, '../renderer/index.html'), { hash: `/boards/${boardId}` })
  }
}

app.whenReady().then(() => {
  configureBrowserSessions(join(__dirname, '../preload/chrome.js'))
  installBrowserDownloads()
  installFileActions(connectionSession)
  installApplicationMenu()
  registerDictation()

  // Renderer mirrors its theme choice here so the native chrome (macOS traffic
  // lights, native scrollbars) and any new window's paint color match.
  ipcMain.on('jaz:set-native-theme', (_event, source) => {
    if (source === 'light' || source === 'dark' || source === 'system') {
      nativeTheme.themeSource = source
    }
  })

  // The traffic lights live above the thread list; the renderer hides them
  // while the list is collapsed rather than moving them around.
  ipcMain.on('jaz:set-window-buttons-visible', (event, visible) => {
    const window = BrowserWindow.fromWebContents(event.sender)
    if (process.platform === 'darwin' && window && typeof visible === 'boolean') {
      window.setWindowButtonVisibility(visible)
    }
  })

  installCredentialEncryption()
  ipcMain.handle('jaz:start-local-backend', (event) => {
    const record = connectionSession.authorizeOwner(event)
    const document = record.document
    return startLocalBackend().then((result) => {
      connectionSession.authorizeOwner(event, document)
      return result
    })
  })
  ipcMain.handle('jaz:get-device-identity', () => getDeviceIdentity())
  ipcMain.handle('jaz:get-device-metadata', () => getDeviceMetadata())
  ipcMain.handle('jaz:configure-notifications', (event, config) => {
    connectionSession.authorizeOwner(event)
    const active = connectionSession.current()
    if (config?.mode !== 'off' && (active.phase !== 'connected' || config?.baseUrl !== active.url || config?.token !== active.session?.token)) {
      return false
    }
    return notifications.configure(config)
  })
  ipcMain.handle('jaz:notifications:notch-access', (event) => {
    connectionSession.authorizeOwner(event)
    return notchAccess()
  })
  ipcMain.handle('jaz:notifications:share-focus', (event) => {
    connectionSession.authorizeOwner(event)
    return shareFocus()
  })
  updates.registerIpc()

  ipcMain.on('jaz:open-board-window', (_event, boardId) => {
    if (typeof boardId === 'string' && boardId !== '') openBoardWindow(boardId)
  })

  ipcMain.on('jaz:open-external-url', (_event, url) => {
    if (typeof url === 'string') openExternalURL(url)
  })

  ipcMain.on('jaz:open-in-main', (_event, path) => {
    if (typeof path === 'string' && path.startsWith('/')) openInMain(path)
  })

  ipcMain.on('jaz:set-preview-url-target-active', (event, active) => {
    if (active === true) previewURLTargets.add(event.sender.id)
    else previewURLTargets.delete(event.sender.id)
  })

  configureAppPermissions(session.defaultSession)
  configureLocalBackendTransport(session.defaultSession, LOCAL_BACKEND_URL)
  if (process.platform === 'darwin') {
    // Development runs inside Electron.app, so it borrows the Jaz icon. Packaged builds keep the bundle icon,
    // which follows the system icon style.
    if (!app.isPackaged) {
      app.dock?.setIcon(appIcon)
    }
    app.setAboutPanelOptions({
      applicationName: APP_NAME,
      applicationVersion: app.getVersion(),
    })
  }
  setupLauncher((window) => connectionSession.attach(window))
  createWindow()
  updates.start()
  app.on('activate', () => {
    if (!mainWindow || mainWindow.isDestroyed()) {
      createWindow()
      return
    }
    mainWindow.show()
    mainWindow.focus()
  })
})

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit()
})

app.on('before-quit', () => {
  notifications.stop()
  teardownLauncher()
  stopLocalBackend('before_quit')
})

import { claudeVoice } from '@preload/claudeVoiceAPI'
import { CLAUDE_VOICE_ARGUMENT } from '@shared/claudeVoice'
import { installClaudeVoice } from '@preload/claudeVoice'
import { contextBridge, ipcRenderer, webUtils } from 'electron'
import { COMPUTER_CHANNEL, type ComputerAPI } from '@shared/computerControl'
import {
  PERMISSION_GUIDE_CHANNEL,
  SYSTEM_PERMISSIONS_CHANNEL,
  type PermissionGuideAPI,
  type SystemPermissionsAPI,
} from '@shared/systemPermissions'
import { SECONDARY_WINDOW_KINDS } from '@shared/windowKind'
import { browserPasswords } from '@preload/browserPasswords'
import { browserDownloads } from '@preload/browserDownloads'
import { installBrowserPasswordCapture } from '@preload/browser'
import { BROWSER_PASSKEY_FALLBACK_ARGUMENT, BROWSER_PRELOAD_ARGUMENT } from '@shared/preview'
import { BROWSER_COMMAND_CHANNEL, type BrowserCommandRequest } from '@shared/browserControl'
import { BROWSER_PROFILE_CHANNELS, type BrowserProfileAPI } from '@shared/browserProfile'
import {
  BROWSER_NAVIGATION_CHANNEL,
  type BrowserNavigationDirection,
} from '../shared/browserNavigation'
import { PREVIEW_FIND_SHORTCUT_CHANNEL } from '../shared/previewFind'
import { BROWSER_CLOSE_SHORTCUT_CHANNEL } from '@shared/browserCloseShortcut'
import { ISLAND_CHANNEL, type IslandAPI, type NotchAccess, type NotificationConfig } from '../shared/notifications'
import type { UpdateStatus } from '../shared/update'
import type { DictationAPI, DictationEvent } from '../shared/dictation'
import type { VoiceCommand, VoiceOverlayAPI, VoiceOverlayState } from '@shared/voice'
import { CONNECTION_SESSION_CHANNEL, LOCAL_SESSION_CHANNEL, type ConnectionSessionAPI, type SessionDocument, type SessionSnapshot } from '@shared/connectionSession'
import { LOCAL_BACKEND_TRANSPORT_URL, LOCAL_BACKEND_URL } from '@shared/localBackend'
import { FILE_ACTIONS_CHANNEL, type FileActionsAPI } from '@shared/fileActions'

const apiBaseUrl = process.env['JAZ_API_URL'] ?? LOCAL_BACKEND_URL

const windowKind = SECONDARY_WINDOW_KINDS.find((kind) => process.argv.includes(`--jaz-${kind}-window`)) ?? 'main'
let previewURLTargetSubscriptions = 0
let sessionDocument: number | undefined

function sessionRequest<T>(request: unknown): T {
  const result = ipcRenderer.sendSync(CONNECTION_SESSION_CHANNEL, request) as { value: T; error?: string }
  if (result.error) {
    throw new Error(result.error)
  }
  return result.value
}

const connectionSession: ConnectionSessionAPI = {
  read: () => {
    const result = sessionRequest<SessionDocument>({ operation: 'read' })
    sessionDocument = result.document
    return result
  },
  update: (request) => sessionRequest<SessionSnapshot>(request),
  local: (document, revision) => ipcRenderer.invoke(LOCAL_SESSION_CHANNEL, document, revision),
  subscribe: (handler) => {
    const listener = (_event: unknown, value: { document: number; snapshot: SessionSnapshot }) => {
      if (value.document === sessionDocument) {
        handler(value.snapshot)
      }
    }
    ipcRenderer.on(CONNECTION_SESSION_CHANNEL, listener)
    return () => ipcRenderer.removeListener(CONNECTION_SESSION_CHANNEL, listener)
  },
}

if (process.argv.includes(CLAUDE_VOICE_ARGUMENT)) {
  installClaudeVoice()
} else if (process.argv.includes(BROWSER_PRELOAD_ARGUMENT)) {
  installBrowserPasswordCapture()
} else {
  contextBridge.exposeInMainWorld('jaz', {
    claudeVoice,
    connectionSession,
    browserPasswords,
    browserDownloads,
    browserPasskeyFallback: process.argv.includes(BROWSER_PASSKEY_FALLBACK_ARGUMENT),
    fileActions: {
      canReveal: (backendUrl, sessionId) => ipcRenderer.invoke(FILE_ACTIONS_CHANNEL, 'canReveal', backendUrl, sessionId),
      reveal: (backendUrl, sessionId, path) => ipcRenderer.invoke(FILE_ACTIONS_CHANNEL, 'reveal', backendUrl, sessionId, path),
    } satisfies FileActionsAPI,
    computer: {
      status: () => ipcRenderer.invoke(COMPUTER_CHANNEL + 'status'),
      begin: (id, session) => ipcRenderer.invoke(COMPUTER_CHANNEL + 'begin', id, session),
      call: (id, action) => ipcRenderer.invoke(COMPUTER_CHANNEL + 'call', id, action),
      end: (id) => ipcRenderer.invoke(COMPUTER_CHANNEL + 'end', id),
      cancel: (id) => ipcRenderer.invoke(COMPUTER_CHANNEL + 'cancel', id),
    } satisfies ComputerAPI,
    systemPermissions: {
      status: () => ipcRenderer.invoke(SYSTEM_PERMISSIONS_CHANNEL + 'status'),
      allow: (permission) => ipcRenderer.invoke(SYSTEM_PERMISSIONS_CHANNEL + 'allow', permission),
    } satisfies SystemPermissionsAPI,
    permissionGuide: {
      drag: () => ipcRenderer.send(PERMISSION_GUIDE_CHANNEL + 'drag'),
      close: () => ipcRenderer.send(PERMISSION_GUIDE_CHANNEL + 'close'),
    } satisfies PermissionGuideAPI,
    voiceOverlay: {
      drag: (point) => ipcRenderer.send('jaz:voice:drag', point),
      resize: (height) => ipcRenderer.send('jaz:voice:resize', height),
      publish: (state) => ipcRenderer.send('jaz:voice:publish', state),
      subscribe: (handler) => {
        const listener = (_event: unknown, state: VoiceOverlayState | null) => handler(state)
        ipcRenderer.on('jaz:voice:state', listener)
        ipcRenderer.send('jaz:voice:ready')
        return () => ipcRenderer.removeListener('jaz:voice:state', listener)
      },
      command: (command) => ipcRenderer.send('jaz:voice:command', command),
      onCommand: (handler) => {
        const listener = (_event: unknown, command: VoiceCommand) => handler(command)
        ipcRenderer.on('jaz:voice:command', listener)
        return () => ipcRenderer.removeListener('jaz:voice:command', listener)
      },
    } satisfies VoiceOverlayAPI,
    island: {
      onState: (listener) => {
        const handler = (_event: unknown, state: Parameters<typeof listener>[0]) => listener(state)
        ipcRenderer.on(`${ISLAND_CHANNEL}state`, handler)
        ipcRenderer.send(`${ISLAND_CHANNEL}ready`)
        return () => ipcRenderer.removeListener(`${ISLAND_CHANNEL}state`, handler)
      },
      command: (command) => ipcRenderer.send(`${ISLAND_CHANNEL}command`, command),
    } satisfies IslandAPI,
    dictation: {
      availability: () => ipcRenderer.invoke('jaz:dictation:availability'),
      start: (id) => ipcRenderer.invoke('jaz:dictation:start', id),
      stop: (id) => ipcRenderer.invoke('jaz:dictation:stop', id),
      cancel: (id) => ipcRenderer.invoke('jaz:dictation:cancel', id),
      onEvent: (handler) => {
        const listener = (_event: unknown, id: string, event: DictationEvent) => handler(id, event)
        ipcRenderer.on('jaz:dictation:event', listener)
        return () => ipcRenderer.removeListener('jaz:dictation:event', listener)
      },
    } satisfies DictationAPI,
    browserProfiles: {
      list: () => ipcRenderer.invoke(BROWSER_PROFILE_CHANNELS.list),
      import: (profileId, selection) => ipcRenderer.invoke(BROWSER_PROFILE_CHANNELS.import, profileId, selection),
    } satisfies BrowserProfileAPI,
    browserCommand: (request: BrowserCommandRequest): Promise<unknown> =>
      ipcRenderer.invoke(BROWSER_COMMAND_CHANNEL, request),
    encryptCredential: (value: string): string => {
      const result = ipcRenderer.sendSync('jaz:credential-encryption', 'encrypt', value) as { value?: string; error?: string }
      if (result.error || !result.value) {
        throw new Error(result.error || 'Credential encryption failed')
      }
      return result.value
    },
    decryptCredential: (value: string): string => {
      const result = ipcRenderer.sendSync('jaz:credential-encryption', 'decrypt', value) as { value?: string; error?: string }
      if (result.error || result.value === undefined) {
        throw new Error(result.error || 'Credential decryption failed')
      }
      return result.value
    },
    apiBaseUrl,
    localBackendTransport: LOCAL_BACKEND_TRANSPORT_URL,
    windowKind,
    pathForFile: (file: File) => webUtils.getPathForFile(file),
    setNativeTheme: (source: 'light' | 'dark' | 'system') =>
      ipcRenderer.send('jaz:set-native-theme', source),
    setWindowButtonsVisible: (visible: boolean) => ipcRenderer.send('jaz:set-window-buttons-visible', visible),
    startLocalBackend: (): Promise<{ ok: boolean; url?: string; key?: string; error?: string }> =>
      ipcRenderer.invoke('jaz:start-local-backend'),
    getDeviceIdentity: (): Promise<{ device_id: string; public_key: string }> =>
      ipcRenderer.invoke('jaz:get-device-identity'),
    getDeviceMetadata: (): Promise<{
      name: string
      platform: string
      device_family: string
      model_identifier: string
      app_version: string
    }> => ipcRenderer.invoke('jaz:get-device-metadata'),
    configureNotifications: (config: NotificationConfig): Promise<boolean> =>
      ipcRenderer.invoke('jaz:configure-notifications', config),
    notchAccess: (): Promise<NotchAccess> => ipcRenderer.invoke('jaz:notifications:notch-access'),
    shareFocusStatus: (): Promise<NotchAccess> => ipcRenderer.invoke('jaz:notifications:share-focus'),
    getUpdateStatus: (): Promise<UpdateStatus> => ipcRenderer.invoke('jaz:get-update-status'),
    installUpdate: (): Promise<{ ok: boolean; error?: string }> =>
      ipcRenderer.invoke('jaz:install-update'),
    onUpdateStatus: (handler: (status: UpdateStatus) => void): (() => void) => {
      const listener = (_event: unknown, status: unknown): void => {
        if (
          typeof status === 'object' &&
          status !== null &&
          'state' in status &&
          typeof status.state === 'string'
        ) {
          handler(status as UpdateStatus)
        }
      }
      ipcRenderer.on('jaz:update-status', listener)
      return () => ipcRenderer.removeListener('jaz:update-status', listener)
    },
    openBoardWindow: (boardId: string) => ipcRenderer.send('jaz:open-board-window', boardId),
    openExternalURL: (url: string) => ipcRenderer.send('jaz:open-external-url', url),
    captureScreenRect: (rect: {
      x: number
      y: number
      width: number
      height: number
    }): Promise<{ ok: boolean; data?: string; denied?: boolean }> =>
      ipcRenderer.invoke('jaz:capture-screen-rect', rect),
    hideLauncher: () => ipcRenderer.send('jaz:hide-launcher'),
    onLauncherShown: (handler: () => void): (() => void) => {
      const listener = (): void => handler()
      ipcRenderer.on('jaz:launcher-shown', listener)
      return () => ipcRenderer.removeListener('jaz:launcher-shown', listener)
    },
    // Board windows deep-link into the main app instead of navigating themselves.
    openInMain: (path: string) => ipcRenderer.send('jaz:open-in-main', path),
    onOpenRoute: (handler: (path: string) => void): (() => void) => {
      const listener = (_event: unknown, path: unknown): void => {
        if (typeof path === 'string') handler(path)
      }
      ipcRenderer.on('jaz:open-route', listener)
      return () => ipcRenderer.removeListener('jaz:open-route', listener)
    },
    onOpenPreviewURL: (handler: (url: string) => void): (() => void) => {
      const listener = (_event: unknown, url: unknown): void => {
        if (typeof url === 'string') handler(url)
      }
      ipcRenderer.on('jaz:open-preview-url', listener)
      previewURLTargetSubscriptions += 1
      if (previewURLTargetSubscriptions === 1) {
        ipcRenderer.send('jaz:set-preview-url-target-active', true)
      }
      return () => {
        ipcRenderer.removeListener('jaz:open-preview-url', listener)
        previewURLTargetSubscriptions = Math.max(0, previewURLTargetSubscriptions - 1)
        if (previewURLTargetSubscriptions === 0) {
          ipcRenderer.send('jaz:set-preview-url-target-active', false)
        }
      }
    },
    onBrowserNavigation: (handler: (direction: BrowserNavigationDirection) => void): (() => void) => {
      const listener = (_event: unknown, direction: unknown): void => {
        if (direction === 'back' || direction === 'forward') handler(direction)
      }
      ipcRenderer.on(BROWSER_NAVIGATION_CHANNEL, listener)
      return () => ipcRenderer.removeListener(BROWSER_NAVIGATION_CHANNEL, listener)
    },
    onBrowserCloseShortcut: (handler: () => void): (() => void) => {
      const listener = () => handler()
      ipcRenderer.on(BROWSER_CLOSE_SHORTCUT_CHANNEL, listener)
      return () => ipcRenderer.removeListener(BROWSER_CLOSE_SHORTCUT_CHANNEL, listener)
    },
    onPreviewFindShortcut: (handler: () => void): (() => void) => {
      const listener = (): void => handler()
      ipcRenderer.on(PREVIEW_FIND_SHORTCUT_CHANNEL, listener)
      return () => ipcRenderer.removeListener(PREVIEW_FIND_SHORTCUT_CHANNEL, listener)
    },
  })
}

import { clientRuntime } from '../clientRuntime'

const TELEMETRY_ENABLED_KEY = 'jaz.telemetry.enabled'
const TELEMETRY_ID_KEY = 'jaz.telemetry.id'
const TELEMETRY_EVENT = 'jaz:telemetry'
const DEFAULT_HOST = 'https://us.i.posthog.com'

type TelemetryEvent =
  | 'app_opened'
  | 'message_sent'
  | 'thread_created'
  | 'loop_created'
  | 'loop_run_started'

type TelemetryProperty = string | number | boolean | null | undefined
type TelemetryProperties = Record<string, TelemetryProperty>

interface MessageSent {
  queued: boolean
  voice?: boolean
  planRequested: boolean
  goalRequested?: boolean
  attachmentCount: number
}

interface ThreadCreated {
  worktree: boolean
  hasDirectory: boolean
  hasModelOverride: boolean
  hasProviderOverride: boolean
  hasReasoningEffort: boolean
}

interface LoopCreated {
  runAfterCreate: boolean
  scheduleKind: string
  status: string
  hasDirectory: boolean
  boardCount: number
  hasModelOverride: boolean
  hasProviderOverride: boolean
  hasReasoningEffort: boolean
}

export function telemetryEnabled(): boolean {
  if (typeof window === 'undefined') return false
  try {
    return window.localStorage.getItem(TELEMETRY_ENABLED_KEY) !== 'false'
  } catch {
    return false
  }
}

export function setTelemetryEnabled(enabled: boolean) {
  if (typeof window === 'undefined') return
  try {
    if (enabled) window.localStorage.removeItem(TELEMETRY_ENABLED_KEY)
    else {
      window.localStorage.setItem(TELEMETRY_ENABLED_KEY, 'false')
      window.localStorage.removeItem(TELEMETRY_ID_KEY)
    }
  } catch {
    return
  }
  window.dispatchEvent(new Event(TELEMETRY_EVENT))
}

export const telemetry = {
  appOpened,
  loopCreated,
  loopRunStarted,
  messageSent,
  threadCreated,
  enabled: telemetryEnabled,
  setEnabled: setTelemetryEnabled,
  subscribe,
}

function appOpened() {
  capture('app_opened')
}

function messageSent(input: MessageSent) {
  capture('message_sent', {
    queued: input.queued,
    voice: input.voice,
    plan_requested: input.planRequested,
    goal_requested: input.goalRequested,
    attachment_count: input.attachmentCount,
  })
}

function threadCreated(input: ThreadCreated) {
  capture('thread_created', {
    worktree: input.worktree,
    has_directory: input.hasDirectory,
    has_model_override: input.hasModelOverride,
    has_provider_override: input.hasProviderOverride,
    has_reasoning_effort: input.hasReasoningEffort,
  })
}

function loopCreated(input: LoopCreated) {
  capture('loop_created', {
    run_after_create: input.runAfterCreate,
    schedule_kind: input.scheduleKind,
    status: input.status,
    has_directory: input.hasDirectory,
    board_count: input.boardCount,
    has_model_override: input.hasModelOverride,
    has_provider_override: input.hasProviderOverride,
    has_reasoning_effort: input.hasReasoningEffort,
  })
}

function loopRunStarted() {
  capture('loop_run_started')
}

function capture(event: TelemetryEvent, properties: TelemetryProperties = {}) {
  const token = import.meta.env.VITE_POSTHOG_TOKEN?.trim()
  if (!token || !telemetryEnabled()) return

  const distinctID = telemetryID()
  if (!distinctID) return

  const payload = {
    api_key: token,
    event,
    distinct_id: distinctID,
    properties: compactProperties({
      ...properties,
      app: 'jaz',
      surface: clientRuntime.windowKind,
      telemetry_version: 1,
    }),
    timestamp: new Date().toISOString(),
  }

  void send(payload)
}

function subscribe(callback: () => void): () => void {
  const listener = () => callback()
  window.addEventListener(TELEMETRY_EVENT, listener)
  window.addEventListener('storage', listener)
  return () => {
    window.removeEventListener(TELEMETRY_EVENT, listener)
    window.removeEventListener('storage', listener)
  }
}

function telemetryID(): string {
  try {
    const stored = window.localStorage.getItem(TELEMETRY_ID_KEY)
    if (stored) return stored
    const id = window.crypto?.randomUUID?.() ?? randomID()
    window.localStorage.setItem(TELEMETRY_ID_KEY, id)
    return id
  } catch {
    return ''
  }
}

function randomID(): string {
  const bytes = new Uint8Array(16)
  if (!window.crypto?.getRandomValues) return `local-${Date.now().toString(16)}-${Math.random().toString(16).slice(2)}`
  window.crypto.getRandomValues(bytes)
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
}

function compactProperties(properties: TelemetryProperties): Record<string, string | number | boolean | null> {
  return Object.fromEntries(
    Object.entries(properties).filter(([, value]) => value !== undefined),
  ) as Record<string, string | number | boolean | null>
}

async function send(payload: object): Promise<void> {
  try {
    await fetch(`${DEFAULT_HOST}/i/v0/e/`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      keepalive: true,
    })
  } catch {
    return
  }
}
